// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.llm.cloudimport okhttp3.Responseimport okhttp3.sse.EventSourceimport okhttp3.sse.EventSourceListenerimport okhttp3.sse.EventSources/** * NOUS — SSE Stream Parser. * * Parses Server-Sent Events (SSE) from cloud LLM APIs (OpenAI, Anthropic, Gemini). * Handles: *   - `data: {...}` lines (JSON content) *   - `data: [DONE]` (stream end) *   - Multi-line data fields *   - Event types (for Anthropic) * * @see <a href="docs/strategy/module-4-strategy-v2.1.md">§5 OpenAI API + StreamParser</a> */class StreamParser {    /**     * Parse a single SSE data line and extract token text.     *     * Supports OpenAI-compatible format:     *   data: {"choices":[{"delta":{"content":"Hello"}}]}     *     * @param dataLine the data portion after "data: "     * @return extracted text token, or null if not a content token     */    fun parseToken(dataLine: String): String? {        if (dataLine.isBlank()) return null        if (dataLine.trim() == "[DONE]") return null        return try {            // Parse JSON (simplified — production would use kotlinx.serialization)            val json = parseSimpleJson(dataLine)            // OpenAI format: choices[0].delta.content            val choices = json?.get("choices") as? List<*>            val firstChoice = choices?.firstOrNull() as? Map<*, *>            val delta = firstChoice?.get("delta") as? Map<*, *>            delta?.get("content") as? String        } catch (e: Exception) {            null        }    }    /**     * Check if a data line indicates stream end.     */    fun isStreamEnd(dataLine: String): Boolean {        return dataLine.trim() == "[DONE]"    }    /**     * Parse Anthropic SSE format.     * Anthropic uses event types: content_block_delta, message_stop, etc.     */    fun parseAnthropicToken(eventType: String, dataLine: String): String? {        if (eventType != "content_block_delta") return null        return try {            val json = parseSimpleJson(dataLine)            val delta = json?.get("delta") as? Map<*, *>            delta?.get("text") as? String        } catch (e: Exception) {            null        }    }    /**     * Parse Gemini SSE format.     * Gemini uses: {"candidates":[{"content":{"parts":[{"text":"Hello"}]}}]}     */    fun parseGeminiToken(dataLine: String): String? {        return try {            val json = parseSimpleJson(dataLine)            val candidates = json?.get("candidates") as? List<*>            val firstCandidate = candidates?.firstOrNull() as? Map<*, *>            val content = firstCandidate?.get("content") as? Map<*, *>            val parts = content?.get("parts") as? List<*>            val firstPart = parts?.firstOrNull() as? Map<*, *>            firstPart?.get("text") as? String        } catch (e: Exception) {            null        }    }    /**     * Simple JSON parser (no external dependency).     * Handles flat objects and nested one level deep.     */    @Suppress("UNCHECKED_CAST")    private fun parseSimpleJson(json: String): Map<String, Any?>? {        return try {            // Use org.json.JSONObject (available on Android)            val jsonObj = org.json.JSONObject(json)            val map = mutableMapOf<String, Any?>()            val keys = jsonObj.keys()            while (keys.hasNext()) {                val key = keys.next()                val value = jsonObj.get(key)                map[key] = when (value) {                    is org.json.JSONArray -> {                        val list = mutableListOf<Any?>()                        for (i in 0 until value.length()) {                            val item = value.get(i)                            list.add(when (item) {                                is org.json.JSONObject -> {                                    val innerMap = mutableMapOf<String, Any?>()                                    val innerKeys = item.keys()                                    while (innerKeys.hasNext()) {                                        val k = innerKeys.next()                                        innerMap[k] = item.get(k)                                    }                                    innerMap                                }                                else -> item                            })                        }                        list                    }                    is org.json.JSONObject -> {                        val innerMap = mutableMapOf<String, Any?>()                        val innerKeys = value.keys()                        while (innerKeys.hasNext()) {                            val k = innerKeys.next()                            innerMap[k] = value.get(k)                        }                        innerMap                    }                    else -> value                }            }            map        } catch (e: Exception) {            null        }    }}